47	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Maximum number of owners a single city may contain; creating an owner in a city that
66	     *  already has this many owners is rejected with 409 Conflict. */
67	    private static final int MAX_OWNERS_PER_CITY = 50;
68	
69	    /** Maximum number of owners that may be created on a single day (by registration date); creating
70	     *  an owner once this many owners already carry today's registration date is rejected with
71	     *  429 Too Many Requests. */
72	    private static final int MAX_OWNERS_PER_DAY = 100;
73	
74	    /** When more than this many owners already carry today's registration date at creation time, the
75	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
76	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
77	
78	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
79	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
80	
81	    private final ClinicService clinicService;
82	
83	    private final OwnerMapper ownerMapper;
84	
85	    private final PetMapper petMapper;
86	
87	    private final VisitMapper visitMapper;
88	
89	    private final TelephoneNormalizer telephoneNormalizer;
90	
91	    private final HouseholdNormalizer householdNormalizer;
92	
93	    private final AddressNormalizer addressNormalizer;
94	
95	    public OwnerRestControllerV1(ClinicService clinicService,
96	                                 OwnerMapper ownerMapper,
97	                                 PetMapper petMapper,
98	                                 VisitMapper visitMapper,
99	                                 TelephoneNormalizer telephoneNormalizer,
100	                                 HouseholdNormalizer householdNormalizer,
101	                                 AddressNormalizer addressNormalizer) {
102	        this.clinicService = clinicService;
103	        this.ownerMapper = ownerMapper;
104	        this.petMapper = petMapper;
105	        this.visitMapper = visitMapper;
106	        this.telephoneNormalizer = telephoneNormalizer;
107	        this.householdNormalizer = householdNormalizer;
108	        this.addressNormalizer = addressNormalizer;
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
114	        Collection<Owner> owners;
115	        if (lastName != null) {
116	            owners = this.clinicService.findOwnerByLastName(lastName);
117	        } else {
118	            owners = this.clinicService.findAllOwners();
119	        }
120	        if (owners.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
129	        Owner owner = this.clinicService.findOwnerById(ownerId);
130	        if (owner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
139	        HttpHeaders headers = new HttpHeaders();
140	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
141	        normalizeOwnerFields(owner);
142	        // Enforce the pre-persistence policies that can reject the new owner outright.
143	        rejectDisallowedOwnerCreation(owner);
144	        // Resolve the owner's household membership: assign the shared 'householdId' when the
145	        // request opts in and joins an existing household, and record the household size. This runs
146	        // before the identity-key check so that check sees the owner's final household id.
147	        applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
148	        // Reject the create when the owner's whole derived identity key (normalized telephone,
149	        // email and household id) already matches an existing owner. This single rule subsumes the
150	        // former separate telephone, email and household duplicate checks.
151	        rejectWhenIdentityInUse(owner);
152	        // Assign the remaining create-time derived fields (namesake count, customer code,
153	        // membership number and bulk-signup warning), each fixed at creation time.
154	        assignDerivedFields(owner);
155	        this.clinicService.saveOwner(owner);
156	        // Emit an audit line for the successful create, carrying the owner id, customer code and
157	        // registration date so the create can be traced from the dedicated AUDIT log.
158	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
159	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
160	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
161	        headers.setLocation(UriComponentsBuilder.newInstance()
162	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
163	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
164	    }
165	
166	    /**
167	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
168	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
169	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
170	     * the sequence of create-time rejections stays readable and a new rule is added as one more
171	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
172	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
173	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
174	     * the household id has been resolved, because that key includes the household id.
175	     *
176	     * @param owner the newly mapped and normalized owner being created
177	     */
178	    private void rejectDisallowedOwnerCreation(Owner owner) {
179	        rejectWhenDailyLimitReached(owner);
180	        rejectWhenCityAtCapacity(owner);
181	    }
182	
183	    /**
184	     * Applies the household-membership rules for a newly normalized owner being created. It finds
185	     * the existing owners who share the owner's household (same last name and address, compared
186	     * case-insensitively with collapsed whitespace), then, using that single lookup: when the
187	     * request opts in via {@code sharesHousehold} and the owner joins an existing household, assigns
188	     * the new owner and every existing member the same stable {@code householdId}; and records the
189	     * owner's {@code householdSize}. Sharing a household is no longer a rejection on its own: a new
190	     * owner is rejected only when its whole identity key matches an existing owner (see
191	     * {@link #rejectWhenIdentityInUse}), and the household id resolved here is part of that key.
192	     *
193	     * @param owner           the newly mapped and normalized owner being created
194	     * @param sharesHousehold whether the request opted in to joining an existing household
195	     */
196	    private void applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
197	        // Identify any existing owners who share a household (same last name and address,
198	        // compared case-insensitively with collapsed whitespace) with the owner being created.
199	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
200	        // When opting in and joining an existing household, assign the new owner and every
201	        // existing member the same stable household identifier derived from the last name and
202	        // address, so all owners of the household share one 'householdId'.
203	        if (sharesHousehold && !householdMembers.isEmpty()) {
204	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
205	            owner.setHouseholdId(householdId);
206	            for (Owner member : householdMembers) {
207	                if (!householdId.equals(member.getHouseholdId())) {
208	                    member.setHouseholdId(householdId);
209	                    this.clinicService.saveOwner(member);
210	                }
211	            }
212	        }
213	        // Record the size of this owner's household after this create, i.e. the number of owners
214	        // sharing this owner's 'householdId' once it is persisted. An owner that shares an existing
215	        // household counts the matched members plus itself; an owner without a shared household is a
216	        // household of one. Fixed at creation time.
217	        owner.setHouseholdSize(owner.getHouseholdId() == null ? 1 : householdMembers.size() + 1);
218	    }
219	
220	    /**
221	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
222	     * has already been resolved: the namesake count, the per-city customer code, the membership
223	     * number derived from that customer code and the registration year, and the bulk-signup warning
224	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
225	     * here keeps {@link #addOwner} focused on the high-level create sequence.
226	     *
227	     * @param owner the owner being created, already normalized and with its household resolved
228	     */
229	    private void assignDerivedFields(Owner owner) {
230	        // Record how many existing owners already share this owner's first and last name
231	        // (compared case-insensitively) before this create, fixed at creation time.
232	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
233	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' from the city, last name and a
234	        // per-city sequence equal to one more than the owners already in that city, fixed at
235	        // creation time.
236	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
237	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
238	        // of the registration date's year (e.g. 'LON-SMI-0007-M26'), fixed at creation time.
239	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
240	        // Flag the create when more than 80 owners have already been created on this owner's
241	        // (adjusted business-day) registration date, fixed at creation time.
242	        owner.setBulkSignupWarning(
243	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
244	    }
245	
246	    /**
247	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
248	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
249	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
250	     * the former separate telephone, email and household duplicate checks: two owners collide only
251	     * when their whole keys are equal, and members of one household with different telephones have
252	     * different keys and are both allowed.
253	     *
254	     * @param owner the owner being created, already normalized and with its household resolved
255	     */
256	    private void rejectWhenIdentityInUse(Owner owner) {
257	        String identityKey = owner.getIdentityKey();
258	        boolean inUse = this.clinicService.findAllOwners().stream()
259	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
260	        if (inUse) {
261	            throw new DuplicateIdentityException(
262	                "An owner with identity key " + identityKey + " already exists");
263	        }
264	    }
265	
266	    /**
267	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
268	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
269	     *
270	     * @param owner the owner being created
271	     */
272	    private void rejectWhenDailyLimitReached(Owner owner) {
273	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
274	            throw new DailyOwnerLimitExceededException(
275	                "The maximum number of owners that may be created today has already been reached");
276	        }
277	    }
278	
279	    /**
280	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
281	     * or more owners, with 409 Conflict.
282	     *
283	     * @param owner the owner being created
284	     */
285	    private void rejectWhenCityAtCapacity(Owner owner) {
286	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
287	            throw new CityCapacityExceededException(
288	                "The city " + owner.getCity() + " already contains the maximum number of owners");
289	        }
290	    }
291	
292	    /**
293	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
294	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
295	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
296	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
297	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
298	     * server's current date. Canonicalising the address here, before the household checks read it,
299	     * ensures duplicate detection and the shared household id both compare the normalized form.
300	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
301	     * duplicate, household and customer-code rules.
302	     *
303	     * @param owner the newly mapped owner to canonicalize
304	     */
305	    private void normalizeOwnerFields(Owner owner) {
306	        // Normalize the address on create so it is stored and returned in canonical form and every
307	        // later comparison (household duplicate detection and the shared household id) uses it.
308	        // A value that is blank after normalization is rejected with 400.
309	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
310	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
311	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
312	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
313	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
314	        // Store the (already syntactically validated) email lower-cased so it is persisted and
315	        // returned in canonical form. A missing email is left untouched.
316	        owner.setEmail(normalizeEmail(owner.getEmail()));
317	        // Validate the optional postcode against the fixed range for the city's region. A postcode
318	        // is checked only when present (it is optional); one out of range for the city's region is
319	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
320	        // value is left unchanged.
321	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
322	        // Default the registration date to the server's current date when the client did not
323	        // supply one, then roll the effective date forward to a business day so a Saturday or
324	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
325	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
326	        // date-derived field (such as the membership number's year segment) and the per-day
327	        // create-limit are computed from.
328	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
329	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
330	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
331	    }
332	
333	    /**
334	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
335	     * following Monday, while a weekday is returned unchanged. Applied to the effective
336	     * registration date (whether supplied in the request or defaulted to the server date) so the
337	     * persisted registration date, every value derived from it and the per-day create-limit all
338	     * use the adjusted business day.
339	     *
340	     * @param date the effective registration date
341	     * @return the same date if it is a weekday, otherwise the following Monday
342	     */
343	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
344	        java.time.LocalDate adjusted = date;
345	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
346	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
347	            adjusted = adjusted.plusDays(1);
348	        }
349	        return adjusted;
350	    }
351	
352	    /**
353	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
354	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
355	     * syntactically valid address (rejecting anything else with 400).
356	     *
357	     * @param email the email value (may be {@code null})
358	     * @return the lower-cased email, or {@code null} if the input was {@code null}
359	     */
360	    private String normalizeEmail(String email) {
361	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
362	    }
363	
364	    /**
365	     * Builds the customer code '<CITY3>-<LAST3>-<NNNN>' for a newly created owner, where CITY3 is
366	     * the upper-cased first three letters of the city, LAST3 is the upper-cased first three letters
367	     * of the last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than
368	     * the owners already in that city (e.g. 'LON-SMI-0007').
369	     *
370	     * @param city     the owner's city
371	     * @param lastName the owner's last name
372	     * @return the formatted customer code
373	     */
374	    private String nextCustomerCode(String city, String lastName) {
375	        String cityPrefix = city.substring(0, Math.min(3, city.length()))
376	            .toUpperCase(java.util.Locale.ROOT);
377	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length()))
378	            .toUpperCase(java.util.Locale.ROOT);
379	        int sequence = countOwnersInCity(city) + 1;
380	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
381	    }
382	
383	    /**
384	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
385	     * fix the per-city sequence of an owner's customer code at creation time.
386	     *
387	     * @param city the city of the owner being created
388	     * @return the number of existing owners in a matching city
389	     */
390	    private int countOwnersInCity(String city) {
391	        return (int) this.clinicService.findAllOwners().stream()
392	            .filter(existing -> existing.getCity() != null
393	                && existing.getCity().equalsIgnoreCase(city))
394	            .count();
395	    }
396	
397	    /**
398	     * Counts the existing owners whose registration date is the given adjusted business day. Used
399	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
400	     * owners already carry that business day as their registration date.
401	     *
402	     * @param date the adjusted business-day registration date to match
403	     * @return the number of existing owners registered on that date
404	     */
405	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
406	        return (int) this.clinicService.findAllOwners().stream()
407	            .filter(existing -> date.equals(existing.getRegistrationDate()))
408	            .count();
409	    }
410	
411	    /**
412	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
413	     * the last two digits of the registration date's year (e.g. 'LON-SMI-0007-M26').
414	     *
415	     * @param customerCode     the owner's customer code
416	     * @param registrationDate the owner's registration date
417	     * @return the formatted membership number
418	     */
419	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
420	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
421	    }
422	
423	    /**
424	     * Returns the existing owners who share the given household, i.e. have the same last name and
425	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
426	     * differing only in letter case or in incidental whitespace are treated as the same household.
427	     *
428	     * @param lastName the last name of the owner being created
429	     * @param address  the address of the owner being created
430	     * @return the existing owners with a matching last name and address (possibly empty)
431	     */
432	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
433	        String householdKey = householdNormalizer.householdKey(lastName, address);
434	        return this.clinicService.findAllOwners().stream()
435	            .filter(existing -> householdNormalizer
436	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
437	            .toList();
438	    }
439	
440	    /**
441	     * Counts the existing owners who share the given first and last name, compared
442	     * case-insensitively. Used to fix an owner's namesake count at creation time.
443	     *
444	     * @param firstName the first name of the owner being created
445	     * @param lastName  the last name of the owner being created
446	     * @return the number of existing owners with a matching first and last name
447	     */
448	    private int countNamesakes(String firstName, String lastName) {
449	        return (int) this.clinicService.findAllOwners().stream()
450	            .filter(existing -> existing.getFirstName() != null
451	                && existing.getFirstName().equalsIgnoreCase(firstName)
452	                && existing.getLastName() != null
453	                && existing.getLastName().equalsIgnoreCase(lastName))
454	            .count();
455	    }
456	
457	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
458	    @Override
459	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
460	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
461	        if (currentOwner == null) {
462	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
463	        }
464	        currentOwner.setAddress(ownerFieldsDto.getAddress());
465	        currentOwner.setCity(ownerFieldsDto.getCity());
466	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
467	        currentOwner.setLastName(ownerFieldsDto.getLastName());
468	        // Normalize the telephone to canonical E.164 form so it is stored and returned
469	        // consistently with create; an unformattable value is rejected with 400.
470	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
471	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
472	        this.clinicService.saveOwner(currentOwner);
473	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
474	    }
475	
476	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
477	    @Transactional
478	    @Override
479	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
480	        Owner owner = this.clinicService.findOwnerById(ownerId);
481	        if (owner == null) {
482	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
483	        }
484	        this.clinicService.deleteOwner(owner);
485	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
486	    }
487	
488	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
489	    @Override
490	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
491	        Owner owner = this.clinicService.findOwnerById(ownerId);
492	        if (owner == null) {
493	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
494	        }
495	        HttpHeaders headers = new HttpHeaders();
496	        Pet pet = petMapper.toPet(petFieldsDto);
497	        owner.setId(ownerId);
498	        pet.setOwner(owner);
499	        pet.getType().setName(null);
500	        this.clinicService.savePet(pet);
501	        PetDto petDto = petMapper.toPetDto(pet);
